class ModelNew(nn.Module):
    """
    Tall-skinny matrix multiplication C = A @ B implemented with a custom
    tiled CuTe GEMM kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_gemm

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
